values ('bbbb0004-0000-4000-8000-000000000012', 'en', null, 'Creative Writing', 'Learn the craft of fiction from the ground up — showing over telling, character, plot, point of view, dialogue, and revision — with hands-on scenes at every step. Built from openly-licensed OER Commons material (CC BY).', null, 'foundations', 18, true, 'science', '{}')
