insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000012', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"\"Showing\" rather than \"telling\" mostly means…","options":["using longer sentences","dramatizing through sensory detail and action instead of stating a conclusion","always writing in first person","adding more adjectives"],"answer":1,"explanation":"Showing lets the reader draw the conclusion from concrete evidence — see ''Showing vs. telling''."},{"prompt":"A character''s motivation is best described as…","options":["what they look like","what they want and why","the setting they live in","the narrator''s opinion of them"],"answer":1,"explanation":"Desire plus reason drives action — see ''Character & motivation''."},{"prompt":"The turning point of highest tension in a story arc is the…","options":["exposition","climax","denouement","inciting incident"],"answer":1,"explanation":"The climax is the peak of the arc — see ''Plot & the story arc''."},{"prompt":"\"She thought he was lying\" is only possible in which point of view?","options":["third-person limited from her perspective","objective (camera-eye)","second person","none — narrators can''t access thoughts"],"answer":0,"explanation":"Interiority requires access to a mind — see ''Point of view & voice''."},{"prompt":"Good dialogue mainly exists to…","options":["fill space between action","reveal character and push the scene forward","explain the plot to readers directly","show off the writer''s ear for slang"],"answer":1,"explanation":"Dialogue is action — see ''Dialogue''."},{"prompt":"A ''concrete detail'' is one that…","options":["is abstract and general","can be perceived by the senses","states how a character feels","summarizes many events at once"],"answer":1,"explanation":"Concrete = perceptible: a chipped mug, not ''sadness'' — see ''Showing vs. telling''."},{"prompt":"An ''inciting incident'' is…","options":["the last scene","the event that upsets the balance and starts the story","a description of setting","the moral of the story"],"answer":1,"explanation":"It disturbs the status quo and launches the arc — see ''Plot & the story arc''."},{"prompt":"Revision is best understood as…","options":["fixing typos","re-seeing the work and reshaping it, not just proofreading","cutting the story in half","writing a second, unrelated draft"],"answer":1,"explanation":"Re-vision = seeing again — see the applied project."}]}'::jsonb, null, 10),
  (2, 'Showing vs. telling — and the power of concrete detail', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Turn flat ''telling'' into vivid ''showing'' using concrete, sensory detail. Warm-up: from the diagnostic, what makes a detail *concrete* rather than abstract?"},{"heading":"The idea","text":"*Telling* states a conclusion — ''She was nervous.'' *Showing* dramatizes the evidence and lets the reader conclude it — ''She checked the door three times, then peeled the label off her water bottle in one long strip.'' The engine of showing is the *concrete detail*: something the senses can register. Abstractions (fear, joy, poverty) are conclusions; concrete details (a bitten fingernail, a fridge holding only ketchup) are evidence. You don''t have to show everything — summary has its uses — but the moments that matter should be dramatized."},{"heading":"Worked example","text":"Weak (telling): ''The kitchen was old and the man was poor and sad.'' Strong (showing): ''One bulb buzzed over the counter. He counted the coins twice, set the kettle on the working burner, and did not turn on the second light.'' Notice what changed: no abstraction survives. ''Old,'' ''poor,'' and ''sad'' become a buzzing bulb, counted coins, and a second light left off — the reader assembles the feeling themselves, and so believes it."},{"heading":"Your turn","text":"Rewrite each telling sentence by showing. (1) ''The party was fun.'' (2) ''He was angry.'' (3) ''The house felt abandoned.'' (4) ''She was exhausted.'' Model responses: (1) ''Someone had kicked off their shoes by the speaker; the punch bowl was down to a pink rind of ice.'' (2) ''He set the mug down hard enough to slosh coffee, and didn''t wipe it up.'' (3) ''Mail fanned across the floor under the slot; a spider had bridged the doorknob to the frame.'' (4) ''She read the same line four times, then let the book tent open on her chest.'' Yours will differ — check that no abstraction sneaks back in."},{"heading":"Common mistakes & exit ticket","text":"Mistake: stacking adjectives (''a big, scary, dark house'') instead of choosing one exact detail. Mistake: ''showing'' then ''telling'' the same beat — ''she slammed the door, furious'' — trust the door. Exit: (a) Is ''grief'' concrete or abstract? (b) Name one strong verb that could replace ''walked angrily.'' Answers: abstract; e.g. ''stormed,'' ''stalked,'' or ''marched.''"}]}'::jsonb, 'Prefer concrete nouns and strong verbs to adjectives and adverbs.', 12),
  (3, 'Character & motivation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Build a character readers believe by grounding them in a specific want and a reason for it. Warm-up: what two things make up a character''s *motivation*?"},{"heading":"The idea","text":"Characters come alive through *desire*. Give a character something they want badly, an *obstacle* between them and it, and a *reason* the want matters, and they will generate action on their own. Round characters also hold *contradiction* — the generous person who can''t forgive, the coward who''s brave for one thing. Reveal all of this through choice under pressure: what a character does when it costs them something tells us who they are far more reliably than what the narrator claims about them."},{"heading":"Worked example","text":"Weak (asserted): ''Mara was determined and brave, a natural leader everyone admired.'' Strong (revealed through a want under pressure): ''The others wanted to wait for morning. Mara was afraid of the dark water too — she just wanted her sister found more. She tied the rope to her waist and stepped off the dock first.'' We''re never told she''s brave or a leader; her want (find the sister) beats her fear (dark water), she acts first, and the label becomes unnecessary."},{"heading":"Your turn","text":"For each, name a concrete want, an obstacle, and one revealing action. (1) A retiree who won''t sell the family diner. (2) A student who cheated once. (3) A new manager afraid of being disliked. Model responses: (1) Want: keep the diner open; obstacle: mounting debt; action: he quietly waives an old regular''s tab and eats the loss. (2) Want: undo the guilt; obstacle: confessing means losing a scholarship; action: she tutors the classmate she outscored, for free. (3) Want: be respected; obstacle: needs to deliver hard feedback; action: she over-praises, then can''t sleep."},{"heading":"Common mistakes & exit ticket","text":"Mistake: describing appearance and backstory while the character wants nothing — a résumé, not a person. Mistake: motivation so vague (''she wanted to be happy'') it can''t drive a scene. Exit: (a) Rewrite a want as a verb: ''brave.'' (b) What reveals character most reliably? Answers: e.g. ''to protect / to prove herself''; a choice made under pressure/cost."}]}'::jsonb, 'A want is a verb: to win, to escape, to be forgiven — not an adjective.', 13),
  (4, 'Plot & the story arc', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Shape events into an arc with rising tension and a turning point. Warm-up: which part of the arc holds the highest tension?"},{"heading":"The idea","text":"A *plot* is not a list of events; it''s events bound by cause and effect around a desire. The classic *arc*: *exposition* (the balance), an *inciting incident* (disturbs it), *rising action* (escalating obstacles and stakes), the *climax* (the decisive confrontation, highest tension), then *falling action* and *resolution* (a new balance). The reliable test of causation: can you join your beats with ''but'' and ''so'' rather than ''and then''? ''And then'' is a sequence; ''but/so'' is a story."},{"heading":"Worked example","text":"Weak (sequence): ''Jonah lost his job, and then he went home, and then he made dinner, and then he slept.'' Strong (arc): ''Jonah lost his job (inciting incident), *so* he hid it from his wife (rising action). *But* she found the severance letter (escalation), *so* he finally admitted he''d been miserable for years (climax) — *and so* they sat at the table and, for the first time, planned something (resolution).'' Same events; now each one causes the next, and a want (to be honest / to be seen) drives it."},{"heading":"Your turn","text":"Turn each ''and then'' chain into a ''but/so'' arc in one or two sentences. (1) A runner trains, races, wins. (2) A child finds a stray dog, keeps it, gives it back. Model responses: (1) ''She trained hard, *but* injured her knee a week out, *so* she raced anyway on a taped joint — and won by refusing to slow on the last curve.'' (2) ''He hid the stray in the shed, *but* it whimpered through dinner, *so* his mother found it — and he learned it already had a collar, and gave it back before he could be told to.''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: mistaking a busy plot for a good one — motion without stakes. Mistake: resolving by coincidence (a lottery win, a sudden rescue) instead of by the protagonist''s choice. Exit: (a) Which conjunctions signal true plot? (b) Name the highest-tension beat of the arc. Answers: ''but'' and ''so''; the climax."}]}'::jsonb, 'Cause and effect: scenes should link with ''and so'' / ''but,'' rarely ''and then.''', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which sentence *shows* rather than tells?","options":["He was extremely nervous about the interview.","His knee bounced under the table; he''d shredded the appointment card to confetti.","The interview made him feel very anxious.","He felt a great deal of anxiety."],"answer":1,"explanation":"Concrete, sensory evidence replaces the stated emotion."},{"prompt":"A round, believable character is best revealed by…","options":["the narrator calling them brave","a detailed physical description","a choice made under pressure","their job title"],"answer":2,"explanation":"Character emerges from choice, especially when it costs something."},{"prompt":"The event that disrupts the opening balance and launches the story is the…","options":["resolution","climax","inciting incident","falling action"],"answer":2,"explanation":"It upsets the status quo and starts the arc."},{"prompt":"You can best test that your scenes form a true plot by joining them with…","options":["''and then''","''meanwhile''","''but'' and ''so''","''suddenly''"],"answer":2,"explanation":"But/so signals cause and effect, not mere sequence."},{"prompt":"A concrete detail is one that…","options":["names an emotion directly","the senses can perceive","summarizes the theme","tells the reader what to feel"],"answer":1,"explanation":"Concrete = perceptible evidence."},{"prompt":"''She wanted to be happy'' is a weak motivation mainly because it is…","options":["too selfish","too specific","too vague to drive a scene","written in past tense"],"answer":2,"explanation":"A usable want is specific and actionable — a verb with an obstacle."}]}'::jsonb, null, 8),
  (6, 'Point of view & voice', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Choose a point of view on purpose and keep its voice consistent. Warm-up: which POV can report a character''s private thoughts?"},{"heading":"The idea","text":"*Point of view* is the position from which a story is told, and it decides what the reader can know. *First person* (''I'') is intimate and can be unreliable. *Third-person limited* (''she'') stays inside one character''s mind — we know only what they know. *Third-person omniscient* roams between minds and can step back to comment. *Objective* (camera-eye) reports only what''s visible, no thoughts. *Voice* is the texture of the telling — word choice, rhythm, attitude — and it should suit both narrator and character. A frightened child and a weary detective should not sound the same."},{"heading":"Worked example","text":"One moment, three POVs. Objective: ''She stood at the window a long time, then closed the blind.'' First person: ''I stood at the window until my feet went cold, telling myself I wasn''t waiting for his car.'' Third limited: ''She lingered at the window, certain that if she looked away, that would be the moment he finally came.'' The objective version withholds; first person confides and reveals unreliability (''telling myself''); third limited grants interiority without the ''I.'' None is ''best'' — each buys a different distance."},{"heading":"Your turn","text":"Rewrite this objective line in the requested POV: ''He read the letter and put it in his pocket.'' (1) First person, guilty. (2) Third limited, relieved. (3) Objective, but tenser. Then (4) name the POV that lets you narrate two characters'' thoughts in one scene. Model responses: (1) ''I read it twice, folded it small, and buried it in my coat where my hand wouldn''t wander.'' (2) ''He read it once and the knot behind his ribs finally loosened; he slid the letter into his pocket like something rescued.'' (3) ''He read the letter standing up, then folded it once and pushed it deep into his pocket.'' (4) Third-person omniscient."},{"heading":"Common mistakes & exit ticket","text":"Mistake: *head-hopping* — sliding into another character''s thoughts mid-scene in a limited POV. Mistake: a first-person narrator reporting things they couldn''t possibly know. Exit: (a) Which POV grants no access to any thoughts? (b) What do we call an unplanned jump between characters'' minds? Answers: objective/camera-eye; a head-hop."}]}'::jsonb, 'Pick a POV and hold it — an unplanned jump between heads is a ''head-hop.''', 13),
  (7, 'Dialogue that does work', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write dialogue that reveals character and advances the scene instead of explaining the plot. Warm-up: what two jobs should a good line of dialogue do at once?"},{"heading":"The idea","text":"Dialogue is *action*, not transcription. Real speech is repetitive and dull; scene dialogue is compressed and pointed. The best lines do at least two jobs — reveal character *and* push the scene — while carrying *subtext*: people rarely say exactly what they mean. Beware the ''As you know, Bob'' trap, where characters tell each other things they both already know so the reader can overhear (*exposition dump*). Attribute with plain ''said''; use *action beats* (''He set down his fork'') to pace, ground, and add subtext instead of fancy tags like ''he expostulated.''"},{"heading":"Worked example","text":"Weak (on-the-nose exposition): ''\"As you know, Dad, since Mom died last year, you''ve been drinking, and I''m worried about you,\" said Ellie sadly.'' Strong (subtext + beats): ''Ellie picked up the bottle by the sink, read the label as if it were new, and set it back down. \"You''re out of orange juice,\" she said. \"I''ll go.\" \"I don''t need juice.\" \"I know,\" she said, and took his keys.'' Nobody names the grief or the drinking; the reader feels both. The taken keys carry the whole argument."},{"heading":"Your turn","text":"Revise each weak exchange to carry subtext (no character stating the obvious). (1) ''\"I am very angry at you for forgetting my birthday.\"'' (2) ''\"I love you but I''m scared of commitment,\" he explained.'' (3) ''\"As you know, we''ve been business partners for ten years.\"'' Model responses: (1) ''\"There''s cake in the fridge if you want it,\" she said. \"I bought it myself.\"'' (2) ''He laughed at the wrong moment, then reached for the check before she could. \"We should go somewhere. Sometime.\"'' (3) ''\"Ten years,\" he said, turning the old photo face-down on the desk. \"Feels about right to end it on a round number.\"''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: ''said-bookisms'' — straining for ''chortled,'' ''ejaculated,'' ''opined'' when ''said'' would vanish and serve better. Mistake: dialogue that only relays plot facts, revealing nothing about who''s speaking. Exit: (a) What is it called when characters state what they both already know for the reader''s benefit? (b) What''s the recommended default dialogue tag? Answers: an exposition dump (the ''As you know, Bob''); ''said.''"}]}'::jsonb, 'Use ''said'' as the default tag — it''s nearly invisible; let the line carry the emotion.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"showing vs. telling","translation":"dramatizing through sensory detail and action rather than stating a conclusion","example":"Instead of ''he was cold,'' show his breath fogging and his hands jammed in his armpits."},{"term":"concrete detail","translation":"a specific, sense-perceptible detail (as opposed to an abstraction)","example":"''A chipped enamel mug'' is concrete; ''sadness'' is abstract."},{"term":"motivation","translation":"what a character wants and the reason it matters to them","example":"Her motivation — to clear her father''s name — drives every risk she takes."},{"term":"inciting incident","translation":"the event that disrupts the opening balance and sets the story in motion","example":"The letter arriving is the inciting incident; before it, nothing was at stake."},{"term":"point of view (POV)","translation":"the vantage point from which a story is told, which sets what the reader can know","example":"In third-person limited POV we know only what she notices, not what he''s thinking."},{"term":"subtext","translation":"the meaning beneath the literal words — what characters imply but don''t say","example":"\"You''re out of orange juice\" carried all the subtext of his grief."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Third-person *limited* point of view means the narration…","options":["knows every character''s thoughts","reports only what can be seen, no thoughts","stays inside a single character''s mind","is told by an ''I'' narrator"],"answer":2,"explanation":"Limited stays within one character''s knowledge."},{"prompt":"A ''head-hop'' is…","options":["a scene-transition device","an unplanned jump into another character''s thoughts in a limited POV","a type of dialogue tag","the climax of the arc"],"answer":1,"explanation":"It breaks the consistency of a limited or first-person POV."},{"prompt":"The recommended default dialogue tag is…","options":["exclaimed","said","opined","muttered"],"answer":1,"explanation":"''Said'' is nearly invisible and keeps focus on the line."},{"prompt":"An ''exposition dump'' in dialogue happens when characters…","options":["interrupt each other","speak in subtext","state things they both already know for the reader''s benefit","use regional slang"],"answer":2,"explanation":"The ''As you know, Bob'' problem."},{"prompt":"Subtext is…","options":["a footnote explaining the scene","the meaning beneath the literal words","the setting of a story","the narrator''s direct commentary"],"answer":1,"explanation":"What is implied but not stated aloud."},{"prompt":"An *action beat* between lines of dialogue is useful because it…","options":["replaces the need for any dialogue","paces the exchange and adds grounding or subtext","tells the reader the theme","must always name an emotion"],"answer":1,"explanation":"Beats control rhythm and reveal character without fancy tags."}]}'::jsonb, null, 8),
  (10, 'Applied project: write and revise a short scene', 'writing', '{"sections":[{"heading":"The task","text":"Write a short scene — roughly 200 to 400 words — in which one character wants something another character won''t give, and then *revise* it once. You''ll produce two versions: a rough draft and a re-seen draft. The point isn''t a perfect first try; it''s learning to see your own work again and reshape it."},{"heading":"Draft it (choose one prompt)","text":"Pick a situation with built-in friction: (a) someone returns a borrowed thing that is now damaged; (b) two people wait for news that only one of them wants; (c) a character quits, and the other tries to talk them out of it. Set a clear *want* for your viewpoint character, pick one *point of view* and hold it, and let *dialogue* and *concrete detail* carry the scene. Resist naming emotions — dramatize them."},{"heading":"Revise it (the re-seeing pass)","text":"Now re-see the draft against this checklist and rewrite accordingly: 1) Circle every abstraction (''angry,'' ''beautiful,'' ''tense'') and replace at least three with concrete, sensory detail. 2) Find one line where you *told* the reader a feeling and cut it — trust the action. 3) Check for a head-hop; keep to your chosen POV. 4) Make one line of dialogue carry subtext instead of stating the obvious. 5) Ensure the scene turns — something is different by the end than at the start."},{"heading":"Self-check rubric","text":"✔ The viewpoint character has a clear, specific want. ✔ Point of view is consistent — no head-hops. ✔ Feeling is shown through concrete detail and action, not asserted. ✔ At least one exchange of dialogue does two jobs (reveals character *and* moves the scene). ✔ The revised draft is visibly different from the first — you re-saw it, you didn''t just proofread. If all five are true, you''ve drafted and revised like a writer."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000012' and l.position = v.pos
);
